// ── Huvudingången ──────────────────────────────────────────────────────────

/**
 * Svara lokalt med nätverkseffekt-mönstret — eller null (då har hela kedjan
 * före redan lämnat null och API-flödet tar över som förr). Ligger efter
 * enhetsekonomi och FÖRE marknadsrytm i widgetens kedja och kan därför aldrig
 * stjäla en fråga från ett tidigare lager. «Moat»/«vallgraven»-familjeorden
 * ägs av moatdjup + basen, «byteskostnader» av mt-05:s lager, «prisfullmakten»
 * av moatdjupet — detta lager äger NÄTVERKS-vinkeln: nätverkseffekten,
 * Metcalfes lag, den tvåsidiga marknaden, tätheten, vinnaren-tar-mest
 * (alla NULL genom kedjan före detta lager — H-fallet bevisar). Samma
 * matchningssemantik som basmotorn: minst ett kärnord krävs, poäng =
 * kärnord × 3 + stärkord, oavgjort → först deklarerade mönstret vinner
 * (strikt >, deterministiskt). Samma fråga ⇒ bitidentiskt svar.
 */
export function svaraLokaltNatverkseffekter(fraga: string, register: RegisterRad[]): LokaltSvar | null {
  const fragaStr = diafri(fraga);
  if (!fragaStr) return null;
  const fragaOrd = fragaStr.split(" ");
  let bast: { svar: LokaltSvar; poang: number } | null = null;
  for (const m of NATVERKSEFFEKT_MONSTER) {
    const karnTraff = m.karnord.filter((nk) => traff(fragaOrd, fragaStr, nk));
    if (karnTraff.length === 0) continue; // krav: minst ett kärnord
    const starkTraff = m.starkord?.filter((nk) => traff(fragaOrd, fragaStr, nk)) ?? [];
    const poang = karnTraff.length * 3 + starkTraff.length;
    if (!bast || poang > bast.poang) bast = { svar: m.bygga(register), poang };
  }
  return bast ? bast.svar : null;
}
